// Formats that password managers and other privacy-aware apps put on the clipboard to say
// "don't record this" (nspasteboard.org conventions on macOS, documented formats on Windows).
const PRIVATE_FORMATS = [
  'org.nspasteboard.concealedtype',
  'org.nspasteboard.transienttype',
  'org.nspasteboard.autogeneratedtype',
  'excludeclipboardcontentfrommonitorprocessing',
  'canincludeinclipboardhistory',
  'canuploadtocloudclipboard',
];

/** True when the clipboard's formats mark its content as secret or not meant to be recorded. */
export function isPrivateClipboard(types: string[]): boolean {
  return types.some((t) => {
    const lower = t.toLowerCase();
    return PRIVATE_FORMATS.some((f) => lower.includes(f));
  });
}
